"use server";

import { prisma } from "../../../../lib/prisma";

export async function generateCertificateData(studentId: string) {
  // 1. Fetch Student Data
  const student = await prisma.user.findUnique({
    where: { id: studentId },
    select: {
      id: true,
      name: true,
      activeProgram: true,
      startDate: true,
      endDate: true,
    },
  });

  if (!student) {
    throw new Error("Student not found");
  }

  // Determine eligibility (has the program ended?)
  // We check if endDate is in the past compared to today.
  // If no endDate, we assume NOT eligible.
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  
  let isEligible = false;
  let finalScore = 0;

  if (student.endDate) {
    const end = new Date(student.endDate);
    end.setHours(0, 0, 0, 0);
    isEligible = today > end;
  }

  // 2. Calculate Final Score IF eligible (or just calculate anyway)
  // We fetch attendances that have scores (evaluation days) between startDate and endDate
  const attendances = await prisma.attendance.findMany({
    where: {
      studentId: student.id,
      session: {
        date: {
          gte: student.startDate || new Date(0),
          lte: student.endDate || new Date(),
        }
      },
      status: "PRESENT"
    },
    include: {
      session: {
        select: {
          date: true,
          programType: true,
        }
      }
    }
  });

  let totalScores = 0;
  let validEvaluationCount = 0;

  attendances.forEach((att) => {
    const sessionDate = new Date(att.session.date);
    const day = sessionDate.getDay();
    const isEvalDay = day === 5 || (day === 6 && att.session.programType === "English on Saturday");

    if (isEvalDay && (att.fluency || att.pronunciation || att.vocabulary)) {
      // Calculate average for this specific day
      const f = att.fluency || 0;
      const p = att.pronunciation || 0;
      const v = att.vocabulary || 0;
      
      // We assume max is 10 per metric => 30 total
      // Let's get the standard average out of 100 for a more traditional certificate feel
      const dayAverageOutOf10 = (f + p + v) / 3;
      const dayAverageOutOf100 = dayAverageOutOf10 * 10; 
      
      totalScores += dayAverageOutOf100;
      validEvaluationCount++;
    }
  });

  if (validEvaluationCount > 0) {
    finalScore = totalScores / validEvaluationCount;
  }

  return {
    student: {
      name: student.name,
      activeProgram: student.activeProgram,
      endDate: student.endDate,
    },
    finalScore: Math.round(finalScore),
    isEligible,
  };
}
